import java.util.*;import dev.zomboid.remains.expand.*;import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.core.BlockPos;
public class NativeDropChecks{static int n;static void check(boolean b){if(!b)throw new AssertionError(n);n++;}public static class Data{public int dirty;public void setDirty(){dirty++;}}public static class Level{public List<ItemEntity> items=new ArrayList<>();public List<?> getEntitiesOfClass(Class<?> c,Object box,java.util.function.Predicate<Object> p){return items.stream().filter(p).toList();}public Hit clip(Object ctx){return new Hit();}}public static class Hit{public String getType(){return "MISS";}public Object getBlockPos(){return new BlockPos(0,0,0);}}
public static void main(String[]args)throws Exception{Data data=new Data();SimpleContainer original=new SimpleContainer(27);for(int i=0;i<27;i++)original.setItem(i,new ItemStack("full"+i,64,64));ExpandedStorage storage=new ExpandedStorage(original,data);Level level=new Level();ItemEntity item=new ItemEntity(new ItemStack("drop:tag",20,64));level.items.add(item);Class<?> collector=Class.forName("dev.zomboid.gore.CorpseCollect");Object changed=FastReflection.call(collector,"collect",level,new BlockPos(0,0,0),null,storage,null);check(changed.equals(1));check(item.discarded);check(storage.getContainerSize()==36);check(storage.getItem(27).tag.equals("drop:tag")&&storage.getItem(27).getCount()==20);check(data.dirty>0);level.items.clear();item=new ItemEntity(new ItemStack("drop:tag",30,64));level.items.add(item);FastReflection.call(collector,"collect",level,new BlockPos(0,0,0),null,storage,null);check(storage.getContainerSize()==36);check(storage.getItem(27).getCount()==50&&item.discarded);System.out.println("Real Gore collector to expanded Remains integration checks: "+n);}}
